r":"Carolina Méndez"},{"id":"a0192026-1119-4000-8000-000000000036","name":"Esquina Alberdi","template":"a0182026-1118-4000-8000-000000000006","location":"Rosario · Echesortu","lat":-32.945,"lng":-60.678,"scale":1.25,"image":6,"author":"Ana Torres"},{"id":"a0192026-1119-4000-8000-000000000037","name":"Galería del Paseo","template":"a0182026-1118-4000-8000-000000000007","location":"Pérez","lat":-32.99,"lng":-60.766,"scale":1.25,"image":7,"author":"Martín Ríos"},{"id":"a0192026-1119-4000-8000-000000000038","name":"Patios del Ombú","template":"a0182026-1118-4000-8000-000000000008","location":"Rosario · Fisherton","lat":-32.919,"lng":-60.734,"scale":1.25,"image":8,"author":"Sofía Roldán"},{"id":"a0192026-1119-4000-8000-000000000039","name":"Ribera del Puente","template":"a0182026-1118-4000-8000-000000000009","location":"San Lorenzo","lat":-32.74,"lng":-60.731,"scale":1.25,"image":9,"author":"Lucía Vega"},{"id":"a0192026-1119-4000-8000-000000000040","name":"Centro Los Aromos","template":"a0182026-1118-4000-8000-000000000010","location":"Villa Gobernador Gálvez","lat":-33.02,"lng":-60.631,"scale":1.25,"image":10,"author":"Carolina Méndez"},{"id":"a0192026-1119-4000-8000-000000000041","name":"Paseo del Sauce","template":"a0182026-1118-4000-8000-000000000001","location":"Rosario · zona oeste","lat":-32.955,"lng":-60.699999999999996,"scale":1.4,"image":11,"author":"Ana Torres"},{"id":"a0192026-1119-4000-8000-000000000042","name":"Casa del Algarrobo","template":"a0182026-1118-4000-8000-000000000002","location":"Rosario · Pichincha","lat":-32.922,"lng":-60.651999999999994,"scale":1.4,"image":12,"author":"Martín Ríos"},{"id":"a0192026-1119-4000-8000-000000000043","name":"Terrazas del Lago","template":"a0182026-1118-4000-8000-000000000003","location":"Funes","lat":-32.908,"lng":-60.806999999999995,"scale":1.4,"image":13,"author":"Sofía Roldán"},{"id":"a0192026-1119-4000-8000-000000000044","name":"Dúplex Los Tilos","template":"a0182026-1118-4000-8000-000000000004","location":"Granadero Baigorria","lat":-32.842999999999996,"lng":-60.702,"scale":1.4,"image":14,"author":"Lucía Vega"},{"id":"a0192026-1119-4000-8000-000000000045","name":"Viviendas del Sol","template":"a0182026-1118-4000-8000-000000000005","location":"Roldán","lat":-32.89,"lng":-60.900999999999996,"scale":1.4,"image":15,"author":"Carolina Méndez"},{"id":"a0192026-1119-4000-8000-000000000046","name":"Esquina Pellegrini","template":"a0182026-1118-4000-8000-000000000006","location":"Rosario · Echesortu","lat":-32.942,"lng":-60.675999999999995,"scale":1.4,"image":1,"author":"Ana Torres"},{"id":"a0192026-1119-4000-8000-000000000047","name":"Taller La Ribera","template":"a0182026-1118-4000-8000-000000000007","location":"Pérez","lat":-32.987,"lng":-60.763999999999996,"scale":1.4,"image":2,"author":"Martín Ríos"},{"id":"a0192026-1119-4000-8000-000000000048","name":"Patios del Camino","template":"a0182026-1118-4000-8000-000000000008","location":"Rosario · Fisherton","lat":-32.916,"lng":-60.732,"scale":1.4,"image":3,"author":"Sofía Roldán"},{"id":"a0192026-1119-4000-8000-000000000049","name":"Ribera de los Álamos","template":"a0182026-1118-4000-8000-000000000009","location":"San Lorenzo","lat":-32.737,"lng":-60.729,"scale":1.4,"image":4,"author":"Lucía Vega"},{"id":"a0192026-1119-4000-8000-000000000050","name":"Centro La Semilla","template":"a0182026-1118-4000-8000-000000000010","location":"Villa Gobernador Gálvez","lat":-33.017,"lng":-60.629,"scale":1.4,"image":5,"author":"Carolina Méndez"}]$data$::jsonb) loop
 select * into strict base from public.obras where id=(spec->>'template')::uuid and canvas_ui->'ensayo'->>'batch'='grows-10-obras-20261118';
 nid:=(spec->>'id')::uuid;
 point:=jsonb_build_object('lat',(spec->>'lat')::numeric,'lng',(spec->>'lng')::numeric);
 pub:=(base.canvas_ui->'publication') || jsonb_build_object('title',spec->>'name','location',(spec->>'location')||' · ubicación de referencia','mapPoint',point,'coverUrl','https://growsapp2.vercel.app/images/obras/demo-'||(spec->>'image')||'.webp','progress',0,'publishedAt',now(),'summary','Proyecto ficticio de ensayo. Planificación inicial de '||round(base.m2_estimados*(spec->>'scale')::numeric)||' m². Se cargaron 6 pliegos, 24 tareas, dependencias y controles. Pendiente de revisión y contratación.','contractorNotes','Seis pliegos en borrador con cómputo y criterios de entrega. Las cotizaciones, adjudicaciones y certificaciones se realizarán durante el circuito de ensayo.','investorNotes','Previsión de financiación de ensayo basada en el presupuesto preliminar. Rondas, derechos y emisión MCU pendientes de validación.','posts',jsonb_build_array());
 insert into public.obras(id,org_id,name,address,estado,tipo_obra,plantas,terreno,m2_estimados,canvas_project_kind,objetivo_texto,canvas_ui)
 values(nid,base.org_id,spec->>'name',(spec->>'location')||' · referencia ficticia','en_curso',base.tipo_obra,base.plantas,round(base.terreno*(spec->>'scale')::numeric),round(base.m2_estimados*(spec->>'scale')::numeric),base.canvas_project_kind,replace(base.objetivo_texto,base.m2_estimados::text,round(base.m2_estimados*(spec->>'scale')::numeric)::text),jsonb_build_object('publication',pub,'ensayo',(base.canvas_ui->'ensayo')||jsonb_build_object('batch','grows-50-obras-20261119','plantilla',base.id,'escala',(spec->>'scale')::numeric,'equipo_propuesto',jsonb_build_object('proyectista',spec->>'author','contratista',(base.canvas_ui->'ensayo'->'equipo_propuesto'->>'contratista')),'presupuesto',jsonb_build_object('moneda','USD ficticio','base',round((base.canvas_ui->'ensayo'->'presupuesto'->>'base')::numeric*(spec->>'scale')::numeric,2),'contingencia_pct',12,'total',round((base.canvas_ui->'ensayo'->'presupuesto'->>'base')::numeric*(spec->>'scale')::numeric*1.12,2))))) on conflict(id) do nothing;
 select count(*) into nodes_count from public.canvas_nodes where obra_id=nid;
 if nodes_count=0 then
 insert into public.canvas_budget_groups(id,obra_id,org_id,name,description,status)
 select md5(nid::text||id::text)::uuid,nid,org_id,name,replace(description,base.name,spec->>'name'),'borrador' from public.canvas_budget_groups where obra_id=base.id;
 insert into public.canvas_nodes(id,obra_id,org_id,parent_id,type,title,description,status,planned_duration_days,progress,position_x,position_y,sort_order,budget_group_id,metadata,capital_amount,capital_currency,executor_kind)
 select md5(nid::text||id::text)::uuid,nid,org_id,case when parent_id is null then null else md5(nid::text||parent_id::text)::uuid end,type,title,
 case when type='tarea' then 'Alcance inicial de ensayo revisión 1. Ver cómputo, presupuesto y aceptación en la planificación.' else description end,
 'pendiente',planned_duration_days,0,position_x,position_y,sort_order,
 case when budget_group_id is null then null else md5(nid::text||budget_group_id::text)::uuid end,
 metadata || jsonb_build_object('responsable_propuesto',spec->>'author','quantity',case when metadata->>'unit' in ('global','unidad') then coalesce((metadata->>'quantity')::numeric,0) else round(coalesce((metadata->>'quantity')::numeric,0)*(spec->>'scale')::numeric,2) end,'budget_usd',round(coalesce(capital_amount,0)*(case when metadata->>'unit' in ('global','unidad') then 1 else (spec->>'scale')::numeric end),2)),
 round(capital_amount*(case when metadata->>'unit' in ('global','unidad') then 1 else (spec->>'scale')::numeric end),2),capital_currency,executor_kind from public.canvas_nodes where obra_id=base.id;
 insert into public.canvas_edges(id,obra_id,org_id,source_node_id,target_node_id,type,is_critical,lag_days,metadata)
 select md5(nid::text||id::text)::uuid,nid,org_id,md5(nid::text||source_node_id::text)::uuid,md5(nid::text||target_node_id::text)::uuid,type,is_critical,lag_days,metadata from public.canvas_edges where obra_id=base.id;
 insert into public.canvas_budget_group_tasks(id,obra_id,org_id,budget_group_id,task_node_id)
 select md5(nid::text||id::text)::uuid,nid,org_id,md5(nid::text||budget_group_id::text)::uuid,md5(nid::text||task_node_id::text)::uuid from public.canvas_budget_group_tasks where obra_id=base.id;
 insert into public.canvas_task_checklist_items(id,obra_id,org_id,task_node_id,title,done,sort_order)
 select md5(nid::text||id::text)::uuid,nid,org_id,md5(nid::text||task_node_id::text)::uuid,title,false,sort_order from public.canvas_task_checklist_items where obra_id=base.id;
 end if;
 update public.obras set canvas_ui=jsonb_set(canvas_ui,'{ensayo,presupuesto}',jsonb_build_object('moneda','USD ficticio','base',(select sum(capital_amount) from public.canvas_nodes where obra_id=nid and type='tarea'),'contingencia_pct',12,'total',(select round(sum(capital_amount)*1.12,2) from public.canvas_nodes where obra_id=nid and type='tarea'))) where id=nid and canvas_ui->'ensayo'->>'batch'='grows-50-obras-20261119';
end loop;
end $seed$;

update public.obras o set
canvas_ui=jsonb_set(canvas_ui,'{publication,posts}',
 coalesce(canvas_ui->'publication'->'posts','[]'::jsonb) || (
 select jsonb_agg(post order by k) from (
 select k, jsonb_build_object(
 'id',md5(o.id::text||'post-inicial-20261119-'||k)::uuid,
 'title',case k when 1 then 'Conocé '||o.name when 2 then 'Pliegos y tareas para cotizar' else 'Cómo vamos a controlar las entregas' end,
 'author',coalesce(o.canvas_ui->'ensayo'->'equipo_propuesto'->>'proyectista','Equipo de proyecto'),
 'publishedAt',now()-make_interval(hours=>(4-k),mins=>abs(hashtext(o.id::text)%55)),
 'coverUrl',case k when 1 then o.canvas_ui->'publication'->>'coverUrl'
 else 'https://growsapp2.vercel.app/images/obras/demo-'||(((abs(hashtext(o.id::text)::bigint)+k)%15)+1)||'.webp' end,
 'category',case k when 1 then 'proyecto' when 2 then 'pliegos' else 'planificacion' end,
 'text',case k
 when 1 then 'Proyecto de ensayo en '||(o.canvas_ui->'publication'->>'location')||'. El alcance preliminar contempla '||o.m2_estimados||' m² y '||o.plantas||' planta(s). Presupuesto inicial USD '||(o.canvas_ui->'ensayo'->'presupuesto'->>'total')||', incluida contingencia del 12%. Imagen conceptual de referencia.'
 when 2 then 'La planificación de '||o.name||' está organizada en seis pliegos: proyecto y permisos, suelo y fundaciones, estructura y cerramientos, instalaciones, terminaciones e inspección. Son 24 tareas con cómputo y presupuesto inicial. La revisión del alcance y la recepción de ofertas son los próximos pasos del ensayo. Imagen conceptual de referencia.'
 else 'Para '||o.name||' se cargaron 72 controles de entrega asociados a las tareas. Cada entrega requerirá medición, evidencia e inspección del proyectista antes de su aceptación. El cronograma inicial incluye 23 dependencias y deberá revisarse antes de iniciar ejecución. Obra de ensayo; imagen conceptual de referencia.'
 end) as post
 from generate_series(1,3) k
 where not exists(select 1 from jsonb_array_elements(coalesce(o.canvas_ui->'publication'->'posts','[]'::jsonb)) x where x->>'id'=md5(o.id::text||'post-inicial-20261119-'||k)::uuid::text)
 ) missing
)),updated_at=now()
where canvas_ui->'ensayo'->>'batch' in ('grows-10-obras-20261118','grows-50-obras-20261119')
and (select count(*) from jsonb_array_elements(coalesce(canvas_ui->'publication'->'posts','[]'::jsonb)) x where x->>'id' in (md5(o.id::text||'post-inicial-20261119-1')::uuid::text,md5(o.id::text||'post-inicial-20261119-2')::uuid::text,md5(o.id::text||'post-inicial-20261119-3')::uuid::text))<3;
